select
  id, room_id, product_id, product_name, batch_no, procedure_id, procedure_name, create_time, update_time, create_by, update_by, is_delete
from bp_factory_room_occupy


        and id = #{id}


        and room_id = #{roomId}


        and product_id = #{productId}


        and product_name = #{productName}


        and batch_no = #{batchNo}


        and procedure_id = #{procedureId}


        and procedure_name = #{procedureName}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and create_by = #{createBy}


        and update_by = #{updateBy}


        and is_delete = #{isDelete}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from bp_factory_room_occupy


        and id = #{id}


        and room_id = #{roomId}


        and product_id = #{productId}


        and product_name = #{productName}


        and batch_no = #{batchNo}


        and procedure_id = #{procedureId}


        and procedure_name = #{procedureName}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and create_by = #{createBy}


        and update_by = #{updateBy}


        and is_delete = #{isDelete}
